import java.io.Serializable;

/**
 * Represents a single row from the Google cluster-usage trace task_events table.
 *
 * Column order in the CSV (per format.pdf):
 *  0 timestamp (microseconds)
 *  1 missing info
 *  2 job ID
 *  3 task index
 *  4 machine ID
 *  5 event type
 *  6 user name
 *  7 scheduling class
 *  8 priority
 *  9 CPU request
 * 10 RAM request
 * 11 disk request
 * 12 different-machine constraint
 */
public class TaskEvent implements Serializable {

    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;
    public static final int UPDATE_PENDING = 7;
    public static final int UPDATE_RUNNING = 8;

    public long timestampMicros;
    public long jobId;
    public long taskIndex;
    public int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestampMicros, long jobId, long taskIndex, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public long getJobId() { return jobId; }
    public int getEventType() { return eventType; }
    public long getTimestampMicros() { return timestampMicros; }
    public long getTimestampMillis() { return timestampMicros / 1000L; }

    public static TaskEvent parse(String line) {
        if (line == null || line.isEmpty()) return null;
        String[] parts = line.split(",", -1);
        if (parts.length < 6) return null;
        try {
            long ts = parts[0].isEmpty() ? 0L : Long.parseLong(parts[0]);
            long jobId = Long.parseLong(parts[2]);
            long taskIndex = parts[3].isEmpty() ? -1L : Long.parseLong(parts[3]);
            int eventType = Integer.parseInt(parts[5]);
            return new TaskEvent(ts, jobId, taskIndex, eventType);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    @Override
    public String toString() {
        return "TaskEvent{ts=" + timestampMicros + ",job=" + jobId
                + ",task=" + taskIndex + ",type=" + eventType + "}";
    }
}
