import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import clusterdata.utils.FileLineSink;
import clusterdata.utils.GzipCsvSources;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.functions.KeySelector;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.KeyedStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

import java.time.Duration;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        System.out.println("output  " + outputPath);
        // Session inactivity gap in seconds; default 600s = 10 minutes.
        final int sesssize = params.getInt("sesssize", 600);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        // --- Sources -------------------------------------------------------
        DataStream<TaskEvent> taskEvents = env
                .addSource(taskSourceOrTest(new GzipCsvSources.TaskSource(taskInput)))
                .returns(TaskEvent.class)
                .name("task-events");

        DataStream<JobEvent> jobEvents = env
                .addSource(jobSourceOrTest(new GzipCsvSources.JobSource(jobInput)))
                .returns(JobEvent.class)
                .name("job-events");

        // --- Session windows over SUBMIT task events -----------------------
        // Only SUBMIT events (event type 0) demarcate stages.
        DataStream<TaskEvent> submits = taskEvents
                .filter(e -> e.getEventType() == TaskEvent.SUBMIT)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(5))
                                .withTimestampAssigner((e, ts) -> e.getTimestampMillis()));

        DataStream<Tuple2<Long, Integer>> sessionCounts = submits
                .keyBy((KeySelector<TaskEvent, Long>) TaskEvent::getJobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .process(new CountSubmitsPerSession())
                .name("session-count");

        // Reduce to the max session size per job.
        DataStream<Tuple2<Long, Integer>> perJobMax = sessionCounts
                .keyBy(t -> t.f0)
                .maxBy(1)
                .name("per-job-max");

        // --- Terminal job events (jobs that have finished) -----------------
        DataStream<Long> finishedJobIds = jobEvents
                .filter(e -> {
                    int t = e.getEventType();
                    return t == JobEvent.FINISH || t == JobEvent.FAIL
                            || t == JobEvent.KILL || t == JobEvent.LOST;
                })
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofSeconds(5))
                                .withTimestampAssigner((e, ts) -> e.getTimestampMillis()))
                .map((MapFunction<JobEvent, Long>) JobEvent::getJobId)
                .returns(Long.class);

        // Connect both streams keyed by jobId and emit final tuple once we
        // know the job has finished and all sessions are accounted for.
        KeyedStream<Tuple2<Long, Integer>, Long> keyedMax = perJobMax.keyBy(t -> t.f0);
        KeyedStream<Long, Long> keyedFinished = finishedJobIds.keyBy(id -> id);

        DataStream<String> output = keyedMax
                .connect(keyedFinished)
                .process(new EmitOnFinished())
                .name("emit-on-finished");

        // --- Sink ----------------------------------------------------------
        if (out != null) {
            @SuppressWarnings({"rawtypes", "unchecked"})
            org.apache.flink.streaming.api.functions.sink.SinkFunction sink = out;
            output.addSink(sink).name("out-sink");
        } else {
            output.addSink(new FileLineSink(outputPath)).name("file-sink");
        }

        env.execute("LongestSessionPerJob");
    }

    /**
     * Counts the number of SUBMIT events falling inside a single session
     * window for one job. Each SUBMIT is a task activity, and duplicate
     * (task_index, resubmit) pairs are counted separately per the spec.
     */
    public static class CountSubmitsPerSession
            extends ProcessWindowFunction<TaskEvent, Tuple2<Long, Integer>, Long, TimeWindow> {
        @Override
        public void process(Long jobId,
                            Context ctx,
                            Iterable<TaskEvent> elements,
                            Collector<Tuple2<Long, Integer>> out) {
            int count = 0;
            for (TaskEvent ignored : elements) {
                count++;
            }
            out.collect(Tuple2.of(jobId, count));
        }
    }

    /**
     * Buffers the per-job max session count and a "finished" flag; emits the
     * final tuple once both have been observed. On bounded inputs Flink
     * advances the watermark to +Inf at end-of-input, so any remaining state
     * for jobs that have finished but whose max arrived late (or vice versa)
     * is still flushed via the end-of-time timer.
     */
    public static class EmitOnFinished
            extends KeyedCoProcessFunction<Long, Tuple2<Long, Integer>, Long, String> {

        private transient ValueState<Integer> maxState;
        private transient ValueState<Boolean> finishedState;
        private transient ValueState<Boolean> emittedState;
        private transient ValueState<Boolean> timerRegistered;

        @Override
        public void open(Configuration parameters) {
            maxState = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("max", Integer.class));
            finishedState = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("finished", Boolean.class));
            emittedState = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("emitted", Boolean.class));
            timerRegistered = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("timer", Boolean.class));
        }

        private void ensureTimer(Context ctx) throws Exception {
            Boolean t = timerRegistered.value();
            if (t == null || !t) {
                // Watermark advances to Long.MAX_VALUE at end of a bounded
                // input; use MAX_VALUE - 1 so the timer definitely fires.
                ctx.timerService().registerEventTimeTimer(Long.MAX_VALUE - 1);
                timerRegistered.update(true);
            }
        }

        private void tryEmit(Long jobId, Collector<String> out) throws Exception {
            Boolean em = emittedState.value();
            if (Boolean.TRUE.equals(em)) return;
            Integer m = maxState.value();
            Boolean f = finishedState.value();
            if (m != null && Boolean.TRUE.equals(f)) {
                out.collect("(" + jobId + "," + m + ")");
                emittedState.update(true);
            }
        }

        @Override
        public void processElement1(Tuple2<Long, Integer> value,
                                    Context ctx,
                                    Collector<String> out) throws Exception {
            Integer cur = maxState.value();
            if (cur == null || value.f1 > cur) {
                maxState.update(value.f1);
            }
            ensureTimer(ctx);
            tryEmit(ctx.getCurrentKey(), out);
        }

        @Override
        public void processElement2(Long jobId,
                                    Context ctx,
                                    Collector<String> out) throws Exception {
            finishedState.update(true);
            ensureTimer(ctx);
            tryEmit(ctx.getCurrentKey(), out);
        }

        @Override
        public void onTimer(long timestamp,
                            OnTimerContext ctx,
                            Collector<String> out) throws Exception {
            tryEmit(ctx.getCurrentKey(), out);
        }
    }
}
